# gui.py
import tkinter as tk
from tkinter import messagebox
from budget_tracker import BudgetTracker
class BudgetTrackerGUI:
    def __init__(self, budget_tracker):
        self.budget_tracker = budget_tracker
        self.root = tk.Tk()
        self.root.title("Budget Tracker")
        self.setup_ui()
    def setup_ui(self):
        self.create_widgets()
        self.layout_widgets()
    def create_widgets(self):
        self.expense_label = tk.Label(self.root, text="Expense Amount:")
        self.expense_entry = tk.Entry(self.root)
        self.expense_desc_label = tk.Label(self.root, text="Expense Description:")
        self.expense_desc_entry = tk.Entry(self.root)
        self.add_expense_button = tk.Button(self.root, text="Add Expense", command=self.add_expense)
        self.saving_label = tk.Label(self.root, text="Saving Amount:")
        self.saving_entry = tk.Entry(self.root)
        self.saving_desc_label = tk.Label(self.root, text="Saving Description:")
        self.saving_desc_entry = tk.Entry(self.root)
        self.add_saving_button = tk.Button(self.root, text="Add Saving", command=self.add_saving)
        self.balance_label = tk.Label(self.root, text="Net Balance:")
    def layout_widgets(self):
        self.expense_label.grid(row=0, column=0, padx=10, pady=5)
        self.expense_entry.grid(row=0, column=1, padx=10, pady=5)
        self.expense_desc_label.grid(row=1, column=0, padx=10, pady=5)
        self.expense_desc_entry.grid(row=1, column=1, padx=10, pady=5)
        self.add_expense_button.grid(row=2, column=0, columnspan=2, pady=10)
        self.saving_label.grid(row=3, column=0, padx=10, pady=5)
        self.saving_entry.grid(row=3, column=1, padx=10, pady=5)
        self.saving_desc_label.grid(row=4, column=0, padx=10, pady=5)
        self.saving_desc_entry.grid(row=4, column=1, padx=10, pady=5)
        self.add_saving_button.grid(row=5, column=0, columnspan=2, pady=10)
        self.balance_label.grid(row=6, column=0, columnspan=2, pady=10)
    def add_expense(self):
        try:
            amount = float(self.expense_entry.get())
            description = self.expense_desc_entry.get()
            self.budget_tracker.add_expense(amount, description)
            messagebox.showinfo("Success", "Expense added successfully!")
        except ValueError:
            messagebox.showerror("Error", "Invalid expense amount!")
    def add_saving(self):
        try:
            amount = float(self.saving_entry.get())
            description = self.saving_desc_entry.get()
            self.budget_tracker.add_saving(amount, description)
            messagebox.showinfo("Success", "Saving added successfully!")
        except ValueError:
            messagebox.showerror("Error", "Invalid saving amount!")
    def run(self):
        self.root.mainloop()
if __name__ == "__main__":
    budget_tracker = BudgetTracker()
    gui = BudgetTrackerGUI(budget_tracker)
    gui.run()
